SELECT o.id, o.org_name AS orgName
FROM sys_user_org uo
INNER JOIN sys_org o ON o.id = uo.org_id
WHERE uo.user_id = #{userId}
  AND uo.tenant_id = #{tenantId}
  AND o.tenant_id = #{tenantId}
  AND o.del_flag = 0
  AND o.org_status = 1
ORDER BY uo.is_main DESC, o.sort ASC, o.id ASC
LIMIT 1

SELECT uo.user_id AS userId, o.org_name AS label
FROM sys_user_org uo
INNER JOIN sys_org o ON o.id = uo.org_id
WHERE uo.tenant_id = #{tenantId}
  AND o.tenant_id = #{tenantId}
  AND o.del_flag = 0
  AND o.org_status = 1
  AND uo.user_id IN

      #{userId}

ORDER BY uo.is_main DESC, o.sort ASC, o.id ASC

SELECT up.user_id AS userId, p.post_name AS label
FROM sys_user_post up
INNER JOIN sys_post p ON p.id = up.post_id
WHERE up.tenant_id = #{tenantId}
  AND p.tenant_id = #{tenantId}
  AND p.del_flag = 0
  AND p.post_status = 1
  AND up.user_id IN

      #{userId}

ORDER BY up.is_main DESC, p.sort ASC, p.id ASC
